bool separated = false;
bool adjacent = false;

for (int i = 0; i < 3; ++i) {
    float min1 = box1.min[i];
    float max1 = box1.max[i];
    float min2 = box2.min[i];
    float max2 = box2.max[i];

    if (max1 < min2 || max2 < min1) {
        separated = true;
        break;
    }
    if (max1 == min2 || max2 == min1) {
        adjacent = true;
    }
}

if (separated) {
    return BoxRelation::Separated;
} else if (adjacent) {
    return BoxRelation::Adjacent;
} else {
    return BoxRelation::Overlapped;
}
// END_CODE

